<script setup>
import {ref,onMounted,watch} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import {api,useAccount,notify,run,upload,date,yuan,refundStatuses,rememberGreeting} from '../lib'
import AddressEditor from '../components/AddressEditor.vue'
const router=useRouter(),route=useRoute(),account=useAccount(),tab=ref(route.query.tab||'profile'),profile=ref({}),data=ref({items:[],total:0}),addresses=ref([]),favorites=ref([]),page=ref(1),addressOpen=ref(false),editing=ref(null),password=ref({old_password:'',password:''}),busy=ref(false),reviewOpen=ref(false),review=ref({images:[]}),localPhotos=ref([])
const tabs=[['profile','个人资料','user'],['orders','我的订单','box'],['favorites','我的收藏','heart'],['addresses','收货地址','truck'],['greetings','祝福语记录','spark'],['refunds','退款记录','edit'],['reviews','我的评价','star'],['password','修改密码','edit']]
async function load(){if(tab.value==='profile')profile.value=await api.get('/user/info');else if(tab.value==='addresses')addresses.value=await api.get('/address/list');else if(tab.value==='favorites')favorites.value=await api.get('/favorite/list');else if(['reviews','refunds','greetings'].includes(tab.value))data.value=await api.get({reviews:'/review/my',refunds:'/refund/my',greetings:'/ai/greeting/list'}[tab.value],{params:{page:page.value}})}
function change(t){if(t==='orders')return router.push('/orders');tab.value=t;page.value=1;router.replace({query:{tab:t}})}
watch(tab,()=>run(load));onMounted(()=>run(load))
async function saveProfile(){if(busy.value)return;busy.value=true;try{let u=await api.put('/user/update',profile.value);account.user=u;localStorage.setItem('userProfile',JSON.stringify(u));notify('个人资料已保存')}finally{busy.value=false}}
async function avatar(e){let file=e.target.files[0];if(file)profile.value.avatar=(await upload(file,'avatar')).url}
async function savePassword(){await api.put('/user/password',password.value);account.logout();notify('密码已修改，请重新登录');router.push('/login')}
async function removeAddress(id){await ElMessageBox.confirm('删除这个收货地址？历史订单中的地址快照会保留。','删除地址');await api.delete('/address/'+id);await load()}
function editReview(r){review.value={...r,images:r.images.map(i=>i.image_url)};localPhotos.value=[];reviewOpen.value=true}
async function addReviewImages(e){let files=[...e.target.files];e.target.value='';if(files.length+review.value.images.length>9)return notify('图片最多9张');busy.value=true;try{for(let file of files)review.value.images.push((await upload(file,'review')).url)}finally{busy.value=false}}
async function saveReview(){await api.put('/review/'+review.value.id,review.value);reviewOpen.value=false;notify('评价已更新');await load()}
</script>
<template><section class="wrap center-layout section"><aside class="center-sidebar"><div class="profile-head"><span class="avatar large"><img v-if="account.user?.avatar" :src="account.user.avatar" alt="我的头像"/><template v-else>{{account.user?.nickname?.slice(0,1)||'花'}}</template></span><h3>{{account.user?.nickname}}</h3><p>愿你的日常，常有花开。</p></div><button v-for="t in tabs" :key="t[0]" :class="{active:tab===t[0]}" @click="change(t[0])"><Icon :name="t[2]" :size="18"/>{{t[1]}}</button><button @click="account.logout();router.push('/')"><Icon name="logout" :size="18"/>退出登录</button></aside><div class="center-content"><div class="section-heading"><div><span class="eyebrow">MY FLEUR</span><h2>{{tabs.find(t=>t[0]===tab)?.[1]}}</h2></div><button v-if="tab==='addresses'" class="btn primary small" @click="editing=null;addressOpen=true">+ 添加地址</button></div><form v-if="tab==='profile'" class="panel stack-form profile-form" @submit.prevent="run(saveProfile)"><label>头像<div class="profile-avatar"><img v-if="profile.avatar" :src="profile.avatar" alt="头像预览"/><input type="file" accept="image/jpeg,image/png,image/webp" @change="run(()=>avatar($event))"/></div></label><label>账号<input :value="profile.username" disabled/></label><label>昵称<input v-model="profile.nickname" required maxlength="60"/></label><label>手机号<input v-model="profile.phone" pattern="1[3-9][0-9]{9}" maxlength="11"/></label><button class="btn primary" :disabled="busy">保存资料</button></form><form v-else-if="tab==='password'" class="panel stack-form profile-form" @submit.prevent="run(savePassword)"><label>原密码<input v-model="password.old_password" type="password" required autocomplete="current-password"/></label><label>新密码<input v-model="password.password" type="password" minlength="8" maxlength="72" required autocomplete="new-password"/></label><button class="btn primary">修改密码并重新登录</button></form><div v-else-if="tab==='addresses'" class="address-grid"><article v-for="a in addresses" :key="a.id" class="panel address-card"><div class="row-between"><h3>{{a.receiver}}</h3><span v-if="a.is_default" class="status-tag">默认地址</span></div><p>{{a.phone}}</p><p>{{a.province}}{{a.city}}{{a.district}}{{a.detail}}</p><div class="row-between"><button class="text-button" @click="editing=a;addressOpen=true">编辑地址</button><button class="text-button muted" @click="run(()=>removeAddress(a.id))">删除</button></div></article><div v-if="!addresses.length" class="empty">添加一个地址，让鲜花找到你。</div></div><div v-else-if="tab==='favorites'"><div class="product-grid three"><ProductCard v-for="p in favorites" :key="p.id" :product="p"/></div><p class="empty" v-if="!favorites.length">还没有收藏，去看看喜欢的鲜花吧。</p></div><div v-else-if="tab==='refunds'"><article v-for="r in data.items" :key="r.id" class="panel record-card"><div class="row-between"><h3>{{refundStatuses[r.refund_status]}}</h3><b>¥ {{yuan(r.refund_amount)}}</b></div><p>{{r.refund_reason}}</p><p v-if="r.refund_remark">{{r.refund_remark}}</p><p class="danger" v-if="r.reject_reason">拒绝原因：{{r.reject_reason}}</p><p class="danger" v-if="r.fail_reason">失败原因：{{r.fail_reason}}</p><p class="subtle">{{date(r.create_time)}} · {{r.refund_no}}</p><RouterLink :to="'/orders?id='+r.order_id" class="text-link">查看关联订单 <Icon name="arrow" :size="15"/></RouterLink></article></div><div v-else-if="tab==='greetings'"><article v-for="g in data.items" :key="g.id" class="panel record-card"><div class="row-between"><h3>{{g.scene}} · {{g.receiver}}</h3><small>{{g.source==='AI'?'AI生成':'本地模板'}}</small></div><p>{{g.content}}</p><div class="row-between"><small>{{date(g.create_time)}}</small><button class="text-button" @click="rememberGreeting(g.content)">用于花卡</button></div></article></div><div v-else-if="tab==='reviews'"><article v-for="r in data.items" :key="r.id" class="panel record-card"><div class="row-between"><h3>{{r.product_name}}</h3><span class="rating">{{'★'.repeat(r.rating)}}</span></div><p>{{r.content}}</p><div class="review-images"><el-image v-for="i in r.images" :key="i.id" :src="i.image_url" :preview-src-list="r.images.map(i=>i.image_url)" fit="cover"/></div><div v-if="r.reply" class="merchant-reply">花礼回复：{{r.reply}}</div><div class="row-between"><span class="subtle">{{date(r.create_time)}} · {{r.status?'公开展示':'已隐藏'}}</span><div><button class="text-button" @click="editReview(r)">修改</button><button class="text-button muted" @click="run(async()=>{await ElMessageBox.confirm('删除这条评价后，不能重复评价此订单商品。','删除评价');await api.delete('/review/'+r.id);await load()})">删除</button></div></div></article></div><template v-if="['refunds','reviews','greetings'].includes(tab)"><div v-if="!data.total" class="empty">这里还没有记录。</div><Pager :page="page" :total="data.total" @change="v=>{page=v;run(load)}"/></template></div></section><AddressEditor v-model="addressOpen" :address="editing" @saved="run(load)"/><el-dialog v-model="reviewOpen" title="修改我的评价" width="560px"><form class="stack-form" @submit.prevent="run(saveReview)"><label>评分<el-rate v-model="review.rating"/></label><label>评价内容<textarea v-model="review.content" required maxlength="2000" rows="4"/></label><div class="upload-previews"><div v-for="(url,i) in review.images" :key="url"><img :src="url" alt="评价图片"/><button type="button" @click="review.images.splice(i,1)">×</button></div></div><input type="file" accept="image/jpeg,image/png,image/webp" multiple @change="run(()=>addReviewImages($event))"/><button class="btn primary" :disabled="busy">保存评价</button></form></el-dialog></template>
